// Plugin catalogue (plugins/index.html, generated by plugins/build_catalog.py): the search
// box filters the list as you type. Without JavaScript it stays hidden and every plugin is
// listed. A file of its own rather than inline code, so the site's Content-Security-Policy
// can stay at script-src 'self'.
(() => {
  const finder = document.querySelector(".finder");
  const box = document.getElementById("find");
  const found = document.getElementById("found");
  const none = document.getElementById("none");
  if (!finder || !box || !found || !none) return;
  const plugins = [...document.querySelectorAll(".plugin")];
  const show = () => {
    const words = box.value.toLowerCase().split(/\s+/).filter(Boolean);
    let shown = 0;
    for (const p of plugins) {
      const hit = words.every((w) => p.dataset.words.includes(w));
      p.hidden = !hit;
      if (hit) shown += 1;
    }
    found.textContent = words.length ? `${shown} of ${plugins.length}` : `${plugins.length} plugins`;
    none.hidden = shown > 0;
  };
  finder.hidden = false;
  box.addEventListener("input", show);
  show();
})();
